// TestFormalConformance replays the cases that the Lean model in
// formal/c1z emits through `lake exe c1z-oracle` (regenerated by
// `make formal-c1z-oracle`) against this engine. The JSON contract is
// formal/c1z/ORACLE_SCHEMA.md.
package pebble

import (
	"bytes"
	"context"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math/rand/v2"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"testing"
	"time"
	"unicode/utf8"

	"github.com/cockroachdb/pebble/v2"
	"github.com/cockroachdb/pebble/v2/vfs"
	"github.com/segmentio/ksuid"

	v2 "github.com/conductorone/baton-sdk/pb/c1/connector/v2"
	reader_v2 "github.com/conductorone/baton-sdk/pb/c1/reader/v2"
	"github.com/conductorone/baton-sdk/pkg/connectorstore"
)

const formalOracleVersion = 1

// hexField decodes a lowercase-hex JSON string. present distinguishes an
// absent field from an empty byte string; null and malformed hex are
// decode errors.
type hexField struct {
	b       string
	present bool
}

func (h *hexField) UnmarshalJSON(data []byte) error {
	var s *string
	if err := json.Unmarshal(data, &s); err != nil {
		return err
	}
	if s == nil {
		return errors.New("hex field is null")
	}
	b, err := hex.DecodeString(*s)
	if err != nil {
		return err
	}
	h.b = string(b)
	h.present = true
	return nil
}

type formalCases struct {
	Version          *int                   `json:"version"`
	Counts           map[string]int         `json:"counts"`
	Keys             []formalKeyCase        `json:"keys"`
	EntitlementStrip []formalStripCase      `json:"entitlement_strip"`
	Writes           []formalWritesCase     `json:"writes"`
	Pagination       []formalPaginationCase `json:"pagination"`
	BareID           []formalBareIDCase     `json:"bare_id"`
	Sync             []formalSyncCase       `json:"sync"`
}

type formalKeyCase struct {
	Name string   `json:"name"`
	Kind string   `json:"kind"`
	RT   hexField `json:"rt"`
	RID  hexField `json:"rid"`
	Ext  hexField `json:"ext"`
	PRT  hexField `json:"prt"`
	PRID hexField `json:"prid"`
	Key  hexField `json:"key"`
}

// formalStripCase has no name in the schema; subtests use the array index.
type formalStripCase struct {
	RT       hexField `json:"rt"`
	RID      hexField `json:"rid"`
	Ext      hexField `json:"ext"`
	Stripped *bool    `json:"stripped"`
	Tail     hexField `json:"tail"`
}

type formalRecord struct {
	RID   hexField `json:"rid"`
	Value *string  `json:"value"`
}

type formalWriteOp struct {
	Op    string          `json:"op"`
	Batch *[]formalRecord `json:"batch"`
	RID   hexField        `json:"rid"`
}

type formalWritesCase struct {
	Name  string          `json:"name"`
	RT    hexField        `json:"rt"`
	Ops   []formalWriteOp `json:"ops"`
	Final *[]formalRecord `json:"final"`
}

type formalPage struct {
	RIDs    *[]hexField `json:"rids"`
	HasNext *bool       `json:"has_next"`
}

type formalPaginationCase struct {
	Name     string        `json:"name"`
	RT       hexField      `json:"rt"`
	RIDs     *[]hexField   `json:"rids"`
	PageSize *uint32       `json:"page_size"`
	Pages    *[]formalPage `json:"pages"`
}

type formalEntRef struct {
	RT  hexField `json:"rt"`
	RID hexField `json:"rid"`
	Ext hexField `json:"ext"`
}

type formalBareIDCase struct {
	Name         string         `json:"name"`
	Entitlements []formalEntRef `json:"entitlements"`
	Lookup       hexField       `json:"lookup"`
	Expected     string         `json:"expected"`
	Found        *formalEntRef  `json:"found"`
}

type formalSyncOp struct {
	Op     string  `json:"op"`
	ID     *string `json:"id"`
	Type   *string `json:"type"`
	Result *string `json:"result"`
}

type formalSyncCase struct {
	Name string         `json:"name"`
	Ops  []formalSyncOp `json:"ops"`
}

func formalCasesPath(t *testing.T) string {
	t.Helper()
	if path := os.Getenv("C1Z_FORMAL_CASES"); path != "" {
		return path
	}
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("runtime.Caller failed; cannot locate formal/c1z/generated/cases.json")
	}
	return filepath.Join(filepath.Dir(file), "..", "..", "..", "..", "formal", "c1z", "generated", "cases.json")
}

// formalFamilyLens returns the length of each family's array, keyed by
// the family's JSON name.
func formalFamilyLens(cases *formalCases) map[string]int {
	return map[string]int{
		"keys":              len(cases.Keys),
		"entitlement_strip": len(cases.EntitlementStrip),
		"writes":            len(cases.Writes),
		"pagination":        len(cases.Pagination),
		"bare_id":           len(cases.BareID),
		"sync":              len(cases.Sync),
	}
}

// decodeFormalCases strictly decodes one oracle document and checks
// version and counts. It does not require any family to be non-empty.
func decodeFormalCases(r io.Reader) (*formalCases, error) {
	dec := json.NewDecoder(r)
	dec.DisallowUnknownFields()
	var cases formalCases
	if err := dec.Decode(&cases); err != nil {
		return nil, fmt.Errorf("decode: %w", err)
	}
	if dec.More() {
		return nil, errors.New("decode: trailing data after the JSON document")
	}
	if cases.Version == nil {
		return nil, fmt.Errorf("oracle version is absent, want %d", formalOracleVersion)
	}
	if *cases.Version != formalOracleVersion {
		return nil, fmt.Errorf("oracle version = %d, want %d", *cases.Version, formalOracleVersion)
	}
	lens := formalFamilyLens(&cases)
	if len(cases.Counts) != len(lens) {
		return nil, fmt.Errorf("counts has %d families %v, want exactly %d", len(cases.Counts), cases.Counts, len(lens))
	}
	for family, n := range lens {
		want, ok := cases.Counts[family]
		if !ok {
			return nil, fmt.Errorf("counts is missing family %q", family)
		}
		if want != n {
			return nil, fmt.Errorf("counts[%q] = %d, but the %q array has %d cases", family, want, family, n)
		}
	}
	return &cases, nil
}

func loadFormalCases(t *testing.T) *formalCases {
	t.Helper()
	path := formalCasesPath(t)
	t.Logf("reading oracle cases from %s", path)
	f, err := os.Open(path)
	if err != nil {
		t.Fatalf("open %s: %v (regenerate with `make formal-c1z-oracle`)", path, err)
	}
	defer f.Close()
	cases, err := decodeFormalCases(f)
	if err != nil {
		t.Fatalf("%s: %v", path, err)
	}
	for family, n := range formalFamilyLens(cases) {
		if n == 0 {
			t.Fatalf("family %q is empty", family)
		}
	}
	return cases
}

func requireHex(t *testing.T, field string, h hexField) string {
	t.Helper()
	if !h.present {
		t.Fatalf("required hex field %q is absent", field)
	}
	return h.b
}

func requireNoHex(t *testing.T, field string, h hexField) {
	t.Helper()
	if h.present {
		t.Fatalf("field %q must be absent for this case", field)
	}
}

// requireProtoString returns s if it is valid UTF-8. proto3 string fields
// reject invalid UTF-8 at marshal time, so such a case cannot reach the
// engine through the v2 API.
func requireProtoString(t *testing.T, field, s string) string {
	t.Helper()
	if !utf8.ValidString(s) {
		t.Fatalf("field %q is not valid UTF-8 (%x); proto3 string fields cannot carry it", field, s)
	}
	return s
}

func requireNamesUnique(t *testing.T, family string, names []string) {
	t.Helper()
	seen := make(map[string]bool, len(names))
	for _, n := range names {
		if n == "" {
			t.Fatalf("%s: case with empty name", family)
		}
		if seen[n] {
			t.Fatalf("%s: duplicate case name %q", family, n)
		}
		seen[n] = true
	}
}

func TestFormalConformance(t *testing.T) {
	replayFormalCases(t, loadFormalCases(t), nil)
}

// formalFailureHook runs in a failed case's cleanup with the case's
// family and its index in that family's array.
type formalFailureHook func(t *testing.T, family string, index int)

// replayFormalCases runs every case of every family as a parallel
// subtest. Cases are independent: each engine-backed case opens its own
// engine in its own temp dir, and onFail reads only the case document.
func replayFormalCases(t *testing.T, cases *formalCases, onFail formalFailureHook) {
	t.Helper()
	run := func(t *testing.T, family, name string, i int, f func(t *testing.T)) {
		t.Helper()
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			if onFail != nil {
				t.Cleanup(func() {
					if t.Failed() {
						onFail(t, family, i)
					}
				})
			}
			f(t)
		})
	}
	t.Run("keys", func(t *testing.T) {
		names := make([]string, 0, len(cases.Keys))
		for _, c := range cases.Keys {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "keys", names)
		for i, c := range cases.Keys {
			run(t, "keys", c.Name, i, func(t *testing.T) { runFormalKeyCase(t, c) })
		}
	})
	t.Run("entitlement_strip", func(t *testing.T) {
		for i, c := range cases.EntitlementStrip {
			run(t, "entitlement_strip", strconv.Itoa(i), i, func(t *testing.T) { runFormalStripCase(t, c) })
		}
	})
	t.Run("writes", func(t *testing.T) {
		names := make([]string, 0, len(cases.Writes))
		for _, c := range cases.Writes {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "writes", names)
		for i, c := range cases.Writes {
			run(t, "writes", c.Name, i, func(t *testing.T) { runFormalWritesCase(t, c) })
		}
	})
	t.Run("pagination", func(t *testing.T) {
		names := make([]string, 0, len(cases.Pagination))
		for _, c := range cases.Pagination {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "pagination", names)
		for i, c := range cases.Pagination {
			run(t, "pagination", c.Name, i, func(t *testing.T) { runFormalPaginationCase(t, c) })
		}
	})
	t.Run("bare_id", func(t *testing.T) {
		names := make([]string, 0, len(cases.BareID))
		for _, c := range cases.BareID {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "bare_id", names)
		for i, c := range cases.BareID {
			run(t, "bare_id", c.Name, i, func(t *testing.T) { runFormalBareIDCase(t, c) })
		}
	})
	t.Run("sync", func(t *testing.T) {
		names := make([]string, 0, len(cases.Sync))
		for _, c := range cases.Sync {
			names = append(names, c.Name)
		}
		requireNamesUnique(t, "sync", names)
		for i, c := range cases.Sync {
			run(t, "sync", c.Name, i, func(t *testing.T) { runFormalSyncCase(t, c) })
		}
	})
}

func runFormalKeyCase(t *testing.T, c formalKeyCase) {
	want := []byte(requireHex(t, "key", c.Key))
	var got []byte
	switch c.Kind {
	case "resource_type":
		requireNoHex(t, "rt", c.RT)
		requireNoHex(t, "rid", c.RID)
		requireNoHex(t, "prt", c.PRT)
		requireNoHex(t, "prid", c.PRID)
		got = encodeResourceTypeKey(requireHex(t, "ext", c.Ext))
	case "resource":
		requireNoHex(t, "ext", c.Ext)
		requireNoHex(t, "prt", c.PRT)
		requireNoHex(t, "prid", c.PRID)
		got = encodeResourceKey(requireHex(t, "rt", c.RT), requireHex(t, "rid", c.RID))
	case "entitlement":
		requireNoHex(t, "prt", c.PRT)
		requireNoHex(t, "prid", c.PRID)
		got = encodeEntitlementIdentityKey(entitlementIdentityFromParts(
			requireHex(t, "rt", c.RT), requireHex(t, "rid", c.RID), requireHex(t, "ext", c.Ext)))
	case "grant":
		got = encodeGrantIdentityKey(grantIdentity{
			entitlement: entitlementIdentityFromParts(
				requireHex(t, "rt", c.RT), requireHex(t, "rid", c.RID), requireHex(t, "ext", c.Ext)),
			principalTypeID: requireHex(t, "prt", c.PRT),
			principalID:     requireHex(t, "prid", c.PRID),
		})
	default:
		t.Fatalf("unknown key kind %q", c.Kind)
	}
	if !bytes.Equal(got, want) {
		t.Fatalf("%s key mismatch:\n got  %x\n want %x", c.Kind, got, want)
	}
}

func runFormalStripCase(t *testing.T, c formalStripCase) {
	if c.Stripped == nil {
		t.Fatal("required field \"stripped\" is absent")
	}
	rt, rid, ext := requireHex(t, "rt", c.RT), requireHex(t, "rid", c.RID), requireHex(t, "ext", c.Ext)
	wantTail := requireHex(t, "tail", c.Tail)
	id := entitlementIdentityFromParts(rt, rid, ext)
	if id.stripped != *c.Stripped || id.tail != wantTail {
		t.Fatalf("entitlementIdentityFromParts(%x, %x, %x) = (stripped=%v, tail=%x), want (stripped=%v, tail=%x)",
			rt, rid, ext, id.stripped, id.tail, *c.Stripped, wantTail)
	}
	if id.resourceTypeID != rt || id.resourceID != rid {
		t.Fatalf("entitlementIdentityFromParts changed owner: got (%x, %x), want (%x, %x)", id.resourceTypeID, id.resourceID, rt, rid)
	}
	if got := id.externalID(); got != ext {
		t.Fatalf("externalID() = %x, want %x", got, ext)
	}
}

// newFormalEngine opens an engine over an in-memory filesystem. The model
// has no filesystem semantics, and the on-disk fsyncs in EndSync serialize
// parallel cases at the device. C1Z_FORMAL_DISK=1 opens on disk instead.
func newFormalEngine(t *testing.T) *Engine {
	t.Helper()
	if os.Getenv("C1Z_FORMAL_DISK") == "1" {
		e, _ := newTestEngine(t)
		return e
	}
	e, _ := newTestEngine(t, WithVFS(vfs.NewMem()))
	return e
}

func newFormalEngineWithSync(t *testing.T) (context.Context, *Engine) {
	t.Helper()
	ctx := context.Background()
	e := newFormalEngine(t)
	if _, err := e.StartNewSync(ctx, connectorstore.SyncTypeFull, ""); err != nil {
		t.Fatalf("StartNewSync: %v", err)
	}
	return ctx, e
}

func formalResource(t *testing.T, rt, rid, displayName string) *v2.Resource {
	t.Helper()
	return v2.Resource_builder{
		Id: v2.ResourceId_builder{
			ResourceType: requireProtoString(t, "rt", rt),
			Resource:     requireProtoString(t, "rid", rid),
		}.Build(),
		DisplayName: requireProtoString(t, "value", displayName),
	}.Build()
}

// listAllFormalResources pages ListResources at MaxPageSize until the
// token is empty.
func listAllFormalResources(ctx context.Context, t *testing.T, e *Engine, rt string) []*v2.Resource {
	t.Helper()
	var out []*v2.Resource
	token := ""
	for {
		resp, err := e.ListResources(ctx, v2.ResourcesServiceListResourcesRequest_builder{
			ResourceTypeId: rt,
			PageSize:       MaxPageSize,
			PageToken:      token,
		}.Build())
		if err != nil {
			t.Fatalf("ListResources: %v", err)
		}
		out = append(out, resp.GetList()...)
		token = resp.GetNextPageToken()
		if token == "" {
			return out
		}
	}
}

func runFormalWritesCase(t *testing.T, c formalWritesCase) {
	rt := requireProtoString(t, "rt", requireHex(t, "rt", c.RT))
	if c.Final == nil {
		t.Fatal("required field \"final\" is absent")
	}
	ctx, e := newFormalEngineWithSync(t)
	for i, op := range c.Ops {
		switch op.Op {
		case "put":
			requireNoHex(t, "rid", op.RID)
			if op.Batch == nil {
				t.Fatalf("op %d: put without \"batch\"", i)
			}
			batch := make([]*v2.Resource, 0, len(*op.Batch))
			for _, r := range *op.Batch {
				if r.Value == nil {
					t.Fatalf("op %d: batch record without \"value\"", i)
				}
				batch = append(batch, formalResource(t, rt, requireHex(t, "rid", r.RID), *r.Value))
			}
			if err := e.PutResources(ctx, batch...); err != nil {
				t.Fatalf("op %d: PutResources: %v", i, err)
			}
		case "delete":
			if op.Batch != nil {
				t.Fatalf("op %d: delete with \"batch\"", i)
			}
			rid := requireProtoString(t, "rid", requireHex(t, "rid", op.RID))
			if err := e.DeleteResourceRecord(ctx, rt, rid); err != nil {
				t.Fatalf("op %d: DeleteResourceRecord: %v", i, err)
			}
		default:
			t.Fatalf("op %d: unknown writes op %q", i, op.Op)
		}
	}
	got := listAllFormalResources(ctx, t, e, rt)
	want := *c.Final
	if len(got) != len(want) {
		t.Fatalf("listed %d resources, want %d: got %v", len(got), len(want), formalResourceSummary(got))
	}
	for i, w := range want {
		if w.Value == nil {
			t.Fatalf("final[%d] without \"value\"", i)
		}
		wantRID := requireHex(t, "rid", w.RID)
		g := got[i]
		if g.GetId().GetResourceType() != rt || g.GetId().GetResource() != wantRID || g.GetDisplayName() != *w.Value {
			t.Fatalf("final[%d] = (rt=%x, rid=%x, value=%q), want (rt=%x, rid=%x, value=%q); full list %v",
				i, g.GetId().GetResourceType(), g.GetId().GetResource(), g.GetDisplayName(), rt, wantRID, *w.Value, formalResourceSummary(got))
		}
	}
}

func formalResourceSummary(rs []*v2.Resource) []string {
	out := make([]string, 0, len(rs))
	for _, r := range rs {
		out = append(out, hex.EncodeToString([]byte(r.GetId().GetResource()))+"="+r.GetDisplayName())
	}
	return out
}

func runFormalPaginationCase(t *testing.T, c formalPaginationCase) {
	rt := requireProtoString(t, "rt", requireHex(t, "rt", c.RT))
	if c.RIDs == nil || c.PageSize == nil || c.Pages == nil {
		t.Fatal("pagination case requires \"rids\", \"page_size\", and \"pages\"")
	}
	ctx, e := newFormalEngineWithSync(t)
	if len(*c.RIDs) > 0 {
		batch := make([]*v2.Resource, 0, len(*c.RIDs))
		for _, h := range *c.RIDs {
			batch = append(batch, formalResource(t, rt, requireHex(t, "rids[]", h), "p"))
		}
		if err := e.PutResources(ctx, batch...); err != nil {
			t.Fatalf("PutResources: %v", err)
		}
	}
	token := ""
	for i, page := range *c.Pages {
		if page.RIDs == nil || page.HasNext == nil {
			t.Fatalf("pages[%d] requires \"rids\" and \"has_next\"", i)
		}
		resp, err := e.ListResources(ctx, v2.ResourcesServiceListResourcesRequest_builder{
			ResourceTypeId: rt,
			PageSize:       *c.PageSize,
			PageToken:      token,
		}.Build())
		if err != nil {
			t.Fatalf("pages[%d]: ListResources: %v", i, err)
		}
		gotRIDs := make([]string, 0, len(resp.GetList()))
		for _, r := range resp.GetList() {
			gotRIDs = append(gotRIDs, hex.EncodeToString([]byte(r.GetId().GetResource())))
		}
		wantRIDs := make([]string, 0, len(*page.RIDs))
		for _, h := range *page.RIDs {
			wantRIDs = append(wantRIDs, hex.EncodeToString([]byte(requireHex(t, "pages[].rids[]", h))))
		}
		if !equalStrings(gotRIDs, wantRIDs) {
			t.Fatalf("pages[%d] rids = %v, want %v", i, gotRIDs, wantRIDs)
		}
		token = resp.GetNextPageToken()
		if gotNext := token != ""; gotNext != *page.HasNext {
			t.Fatalf("pages[%d] has_next = %v, want %v", i, gotNext, *page.HasNext)
		}
		if token == "" && i != len(*c.Pages)-1 {
			t.Fatalf("token ended after page %d, want %d pages", i, len(*c.Pages))
		}
	}
	if token != "" {
		t.Fatalf("token still set after the last expected page %d", len(*c.Pages)-1)
	}
}

func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func runFormalBareIDCase(t *testing.T, c formalBareIDCase) {
	lookup := requireProtoString(t, "lookup", requireHex(t, "lookup", c.Lookup))
	ctx, e := newFormalEngineWithSync(t)
	ents := make([]*v2.Entitlement, 0, len(c.Entitlements))
	for _, ref := range c.Entitlements {
		rt := requireProtoString(t, "rt", requireHex(t, "rt", ref.RT))
		rid := requireProtoString(t, "rid", requireHex(t, "rid", ref.RID))
		ext := requireProtoString(t, "ext", requireHex(t, "ext", ref.Ext))
		ents = append(ents, v2.Entitlement_builder{
			Id: ext,
			Resource: v2.Resource_builder{
				Id: v2.ResourceId_builder{ResourceType: rt, Resource: rid}.Build(),
			}.Build(),
		}.Build())
	}
	if len(ents) > 0 {
		if err := e.PutEntitlements(ctx, ents...); err != nil {
			t.Fatalf("PutEntitlements: %v", err)
		}
	}
	switch c.Expected {
	case "not_found", "ambiguous":
		if c.Found != nil {
			t.Fatalf("expected %q with a \"found\" object", c.Expected)
		}
	case "found":
		if c.Found == nil {
			t.Fatal("expected \"found\" without a \"found\" object")
		}
	default:
		t.Fatalf("unknown bare_id expected %q", c.Expected)
	}
	resp, err := e.GetEntitlement(ctx, reader_v2.EntitlementsReaderServiceGetEntitlementRequest_builder{
		EntitlementId: lookup,
	}.Build())
	var got string
	switch {
	case err == nil:
		got = "found"
	case errors.Is(err, pebble.ErrNotFound):
		got = "not_found"
	case errors.Is(err, ErrAmbiguousExternalID):
		got = "ambiguous"
	default:
		t.Fatalf("GetEntitlement(%x): unexpected error: %v", lookup, err)
	}
	if got != c.Expected {
		t.Fatalf("GetEntitlement(%x) = %s (err=%v), want %s", lookup, got, err, c.Expected)
	}
	if got != "found" {
		return
	}
	wantRT, wantRID, wantExt := requireHex(t, "found.rt", c.Found.RT), requireHex(t, "found.rid", c.Found.RID), requireHex(t, "found.ext", c.Found.Ext)
	ent := resp.GetEntitlement()
	gotRT, gotRID, gotExt := ent.GetResource().GetId().GetResourceType(), ent.GetResource().GetId().GetResource(), ent.GetId()
	if gotRT != wantRT || gotRID != wantRID || gotExt != wantExt {
		t.Fatalf("GetEntitlement(%x) = (rt=%x, rid=%x, ext=%x), want (rt=%x, rid=%x, ext=%x)",
			lookup, gotRT, gotRID, gotExt, wantRT, wantRID, wantExt)
	}
}

func formalSyncType(t *testing.T, s string, allowAny bool) connectorstore.SyncType {
	t.Helper()
	switch s {
	case "full":
		return connectorstore.SyncTypeFull
	case "partial":
		return connectorstore.SyncTypePartial
	case "resources_only":
		return connectorstore.SyncTypeResourcesOnly
	case "any":
		if allowAny {
			return connectorstore.SyncTypeAny
		}
	}
	t.Fatalf("unknown sync type %q", s)
	return ""
}

// formalSyncIDs maps the oracle's symbolic sync ids to KSUIDs, which
// codec.EncodeSyncID requires, and back.
type formalSyncIDs struct {
	toEngine   map[string]string
	fromEngine map[string]string
}

func (m *formalSyncIDs) engineID(symbolic string) string {
	id, known := m.candidateID(symbolic)
	if !known {
		m.bind(symbolic, id)
	}
	return id
}

// candidateID returns the KSUID bound to symbolic, or a fresh unbound one.
// start_new binds a fresh id only after the engine accepts it, so a
// refused start_new leaves no mapping behind.
func (m *formalSyncIDs) candidateID(symbolic string) (string, bool) {
	if id, ok := m.toEngine[symbolic]; ok {
		return id, true
	}
	return ksuid.New().String(), false
}

func (m *formalSyncIDs) bind(symbolic, id string) {
	m.toEngine[symbolic] = id
	m.fromEngine[id] = symbolic
}

func runFormalSyncCase(t *testing.T, c formalSyncCase) {
	ctx := context.Background()
	e := newFormalEngine(t)
	if len(c.Ops) == 0 {
		t.Fatal("sync case with no ops")
	}
	ids := &formalSyncIDs{toEngine: map[string]string{}, fromEngine: map[string]string{}}
	for i, op := range c.Ops {
		if op.Result == nil {
			t.Fatalf("op %d (%s): required field \"result\" is absent", i, op.Op)
		}
		want := *op.Result
		requireID := func() string {
			if op.ID == nil {
				t.Fatalf("op %d (%s): required field \"id\" is absent", i, op.Op)
			}
			return requireProtoString(t, "id", *op.ID)
		}
		requireType := func() string {
			if op.Type == nil {
				t.Fatalf("op %d (%s): required field \"type\" is absent", i, op.Op)
			}
			return *op.Type
		}
		requireNoIDOrType := func() {
			if op.ID != nil || op.Type != nil {
				t.Fatalf("op %d (%s): \"id\" and \"type\" must be absent", i, op.Op)
			}
		}
		var got string
		switch op.Op {
		case "start_new":
			id := requireID()
			st := formalSyncType(t, requireType(), false)
			switch want {
			case "ok", "sync_in_progress":
			default:
				t.Fatalf("op %d: unknown start_new result %q", i, want)
			}
			// ResetForNewSync returns an unwrapped error while a sync
			// started by StartNewSync* is open; the flag is read before
			// the call.
			fresh := e.IsFreshSync()
			engineID, known := ids.candidateID(id)
			gotID, err := e.StartNewSyncWithID(ctx, st, engineID, "")
			switch {
			case err == nil:
				if gotID != engineID {
					t.Fatalf("op %d: StartNewSyncWithID returned %q, want %q", i, gotID, engineID)
				}
				if !known {
					ids.bind(id, engineID)
				}
				got = "ok"
			case fresh:
				got = "sync_in_progress"
			default:
				t.Fatalf("op %d: StartNewSyncWithID(%q as %s): %v", i, id, engineID, err)
			}
		case "write":
			requireNoIDOrType()
			switch want {
			case "allowed", "no_current_sync", "engine_sealed":
			default:
				t.Fatalf("op %d: unknown write result %q", i, want)
			}
			err := e.PutResources(ctx, formalResource(t, "user", "u1", "w"))
			switch {
			case err == nil:
				got = "allowed"
			case errors.Is(err, ErrEngineSealed):
				got = "engine_sealed"
			case errors.Is(err, ErrNoCurrentSync):
				got = "no_current_sync"
			default:
				t.Fatalf("op %d: PutResources: unexpected error: %v", i, err)
			}
		case "end":
			requireNoIDOrType()
			switch want {
			case "ok", "no_current_sync":
			default:
				t.Fatalf("op %d: unknown end result %q", i, want)
			}
			// endSync returns an unwrapped error, not ErrNoCurrentSync,
			// when no sync is bound; the binding is read before the call.
			unbound := e.CurrentSyncID() == ""
			err := e.EndSync(ctx)
			switch {
			case err == nil:
				got = "ok"
			case unbound || errors.Is(err, ErrNoCurrentSync):
				got = "no_current_sync"
			default:
				t.Fatalf("op %d: EndSync: unexpected error: %v", i, err)
			}
		case "resume":
			id := requireID()
			if op.Type != nil {
				t.Fatalf("op %d (resume): \"type\" must be absent", i)
			}
			switch want {
			case "ok", "not_found":
			default:
				t.Fatalf("op %d: unknown resume result %q", i, want)
			}
			_, err := e.ResumeSync(ctx, connectorstore.SyncTypeAny, ids.engineID(id))
			switch {
			case err == nil:
				got = "ok"
			case errors.Is(err, pebble.ErrNotFound):
				got = "not_found"
			default:
				t.Fatalf("op %d: ResumeSync(%q): unexpected error: %v", i, id, err)
			}
		case "latest_finished":
			if op.ID != nil {
				t.Fatalf("op %d (latest_finished): \"id\" must be absent", i)
			}
			st := formalSyncType(t, requireType(), true)
			id, err := e.LatestFinishedSyncID(ctx, st)
			if err != nil {
				t.Fatalf("op %d: LatestFinishedSyncID: %v", i, err)
			}
			switch symbolic, ok := ids.fromEngine[id]; {
			case id == "":
				got = "none"
			case ok:
				got = symbolic
			default:
				t.Fatalf("op %d: LatestFinishedSyncID returned %q, which no start_new or resume op named", i, id)
			}
		default:
			t.Fatalf("op %d: unknown sync op %q", i, op.Op)
		}
		if got != want {
			t.Fatalf("op %d (%s): got %q, want %q", i, op.Op, got, want)
		}
	}
}

// MarshalJSON lets a failed property case log its decoded response.
// An absent field marshals as null.
func (h hexField) MarshalJSON() ([]byte, error) {
	if !h.present {
		return []byte("null"), nil
	}
	return json.Marshal(hex.EncodeToString([]byte(h.b)))
}

// formalRequest is the `c1z-oracle --respond` request document: the case
// document without counts and without expected fields.
type formalRequest struct {
	Version          int                       `json:"version"`
	Keys             []formalKeyRequest        `json:"keys"`
	EntitlementStrip []formalStripRequest      `json:"entitlement_strip"`
	Writes           []formalWritesRequest     `json:"writes"`
	Pagination       []formalPaginationRequest `json:"pagination"`
	BareID           []formalBareIDRequest     `json:"bare_id"`
	Sync             []formalSyncRequest       `json:"sync"`
}

// Request byte strings are hex already; nil means the field is absent.
type formalKeyRequest struct {
	Name string  `json:"name"`
	Kind string  `json:"kind"`
	RT   *string `json:"rt,omitempty"`
	RID  *string `json:"rid,omitempty"`
	Ext  *string `json:"ext,omitempty"`
	PRT  *string `json:"prt,omitempty"`
	PRID *string `json:"prid,omitempty"`
}

type formalStripRequest struct {
	RT  string `json:"rt"`
	RID string `json:"rid"`
	Ext string `json:"ext"`
}

type formalRecordRequest struct {
	RID   string `json:"rid"`
	Value string `json:"value"`
}

type formalWriteOpRequest struct {
	Op    string                `json:"op"`
	Batch []formalRecordRequest `json:"batch,omitempty"`
	RID   *string               `json:"rid,omitempty"`
}

type formalWritesRequest struct {
	Name string                 `json:"name"`
	RT   string                 `json:"rt"`
	Ops  []formalWriteOpRequest `json:"ops"`
}

type formalPaginationRequest struct {
	Name     string   `json:"name"`
	RT       string   `json:"rt"`
	RIDs     []string `json:"rids"`
	PageSize uint32   `json:"page_size"`
}

type formalEntRefRequest struct {
	RT  string `json:"rt"`
	RID string `json:"rid"`
	Ext string `json:"ext"`
}

type formalBareIDRequest struct {
	Name         string                `json:"name"`
	Entitlements []formalEntRefRequest `json:"entitlements"`
	Lookup       string                `json:"lookup"`
}

type formalSyncOpRequest struct {
	Op   string  `json:"op"`
	ID   *string `json:"id,omitempty"`
	Type *string `json:"type,omitempty"`
}

type formalSyncRequest struct {
	Name string                `json:"name"`
	Ops  []formalSyncOpRequest `json:"ops"`
}

func hexPtr(s string) *string {
	h := hex.EncodeToString([]byte(s))
	return &h
}

func hexStr(s string) string { return hex.EncodeToString([]byte(s)) }

func strPtr(s string) *string { return &s }

type formalGen struct{ r *rand.Rand }

// rawByte is biased toward the bytes the key encoders treat specially.
func (g formalGen) rawByte() byte {
	switch n := g.r.IntN(12); {
	case n < 2:
		return 0x00
	case n < 4:
		return 0x01
	case n < 6:
		return ':'
	case n < 10:
		return "abxyz"[g.r.IntN(5)]
	default:
		return formalHighBytes[g.r.IntN(len(formalHighBytes))]
	}
}

var formalHighBytes = func() []byte {
	var out []byte
	for b := byte(0x80); ; b++ {
		out = append(out, b)
		if b == 0xff {
			return out
		}
	}
}()

// rawBytes returns arbitrary bytes, not necessarily valid UTF-8.
func (g formalGen) rawBytes(minLen, maxLen int) string {
	b := make([]byte, minLen+g.r.IntN(maxLen-minLen+1))
	for i := range b {
		b[i] = g.rawByte()
	}
	return string(b)
}

var formalUTF8Fragments = []string{
	"a", "b", "z", "0", "9", "_", "-", ":", "user", "group", "é", "日本", "ß",
}

// utf8String concatenates whole fragments, so the result is valid UTF-8.
func (g formalGen) utf8String(minFrags, maxFrags int) string {
	frags := make([]string, minFrags+g.r.IntN(maxFrags-minFrags+1))
	for i := range frags {
		frags[i] = formalUTF8Fragments[g.r.IntN(len(formalUTF8Fragments))]
	}
	return strings.Join(frags, "")
}

// entitlementExt sometimes returns rt:rid:tail so the stripped branch of
// entitlementIdentityFromParts is reached.
func (g formalGen) entitlementExt(rt, rid string, stripProb int, part func() string) string {
	if g.r.IntN(stripProb) == 0 {
		return rt + ":" + rid + ":" + part()
	}
	return part()
}

func (g formalGen) keyCase(i int) formalKeyRequest {
	c := formalKeyRequest{Name: fmt.Sprintf("property/keys/%d", i)}
	part := func() string { return g.rawBytes(0, 6) }
	nonEmpty := func() string { return g.rawBytes(1, 6) }
	switch g.r.IntN(4) {
	case 0:
		c.Kind = "resource_type"
		c.Ext = hexPtr(part())
	case 1:
		c.Kind = "resource"
		c.RT, c.RID = hexPtr(part()), hexPtr(part())
	case 2:
		c.Kind = "entitlement"
		rt, rid := nonEmpty(), nonEmpty()
		c.RT, c.RID, c.Ext = hexPtr(rt), hexPtr(rid), hexPtr(g.entitlementExt(rt, rid, 3, part))
	default:
		c.Kind = "grant"
		rt, rid := nonEmpty(), nonEmpty()
		c.RT, c.RID, c.Ext = hexPtr(rt), hexPtr(rid), hexPtr(g.entitlementExt(rt, rid, 3, nonEmpty))
		c.PRT, c.PRID = hexPtr(nonEmpty()), hexPtr(nonEmpty())
	}
	return c
}

func (g formalGen) stripCase() formalStripRequest {
	rt, rid := g.rawBytes(1, 6), g.rawBytes(1, 6)
	ext := g.entitlementExt(rt, rid, 2, func() string { return g.rawBytes(0, 6) })
	return formalStripRequest{RT: hexStr(rt), RID: hexStr(rid), Ext: hexStr(ext)}
}

func (g formalGen) writesCase(i int) formalWritesRequest {
	pool := make([]string, 1+g.r.IntN(5))
	for j := range pool {
		pool[j] = g.utf8String(1, 3)
	}
	c := formalWritesRequest{Name: fmt.Sprintf("property/writes/%d", i), RT: hexStr(g.utf8String(1, 3))}
	value := 0
	for range 1 + g.r.IntN(6) {
		if g.r.IntN(3) == 0 {
			rid := pool[g.r.IntN(len(pool))]
			if g.r.IntN(4) == 0 {
				rid = "absent" + g.utf8String(0, 2)
			}
			c.Ops = append(c.Ops, formalWriteOpRequest{Op: "delete", RID: hexPtr(rid)})
			continue
		}
		batch := make([]formalRecordRequest, 1+g.r.IntN(4))
		for j := range batch {
			value++
			batch[j] = formalRecordRequest{RID: hexStr(pool[g.r.IntN(len(pool))]), Value: fmt.Sprintf("v%d", value)}
		}
		c.Ops = append(c.Ops, formalWriteOpRequest{Op: "put", Batch: batch})
	}
	return c
}

func (g formalGen) paginationCase(i int) formalPaginationRequest {
	n := g.r.Uint32N(13)
	seen := map[string]bool{}
	rids := []string{}
	for added := uint32(0); added < n; {
		rid := g.utf8String(1, 4)
		if seen[rid] {
			continue
		}
		seen[rid] = true
		rids = append(rids, hexStr(rid))
		added++
	}
	g.r.Shuffle(len(rids), func(a, b int) { rids[a], rids[b] = rids[b], rids[a] })
	sizes := []uint32{0, 1, 2, 3, 5, 7, n, n + 1, 13}
	return formalPaginationRequest{
		Name:     fmt.Sprintf("property/pagination/%d", i),
		RT:       hexStr(g.utf8String(1, 3)),
		RIDs:     rids,
		PageSize: sizes[g.r.IntN(len(sizes))],
	}
}

func (g formalGen) bareIDCase(i int) formalBareIDRequest {
	type owner struct{ rt, rid string }
	owners := make([]owner, 1+g.r.IntN(3))
	for j := range owners {
		owners[j] = owner{rt: g.utf8String(1, 2), rid: g.utf8String(1, 2)}
	}
	extPool := []string{"member", "admin", "é", "日本"}
	type ent struct{ rt, rid, ext string }
	seen := map[ent]bool{}
	c := formalBareIDRequest{Name: fmt.Sprintf("property/bare_id/%d", i)}
	var exts []string
	for want := 1 + g.r.IntN(5); len(c.Entitlements) < want; {
		o := owners[g.r.IntN(len(owners))]
		e := ent{o.rt, o.rid, g.entitlementExt(o.rt, o.rid, 4, func() string { return extPool[g.r.IntN(len(extPool))] })}
		if seen[e] {
			continue
		}
		seen[e] = true
		exts = append(exts, e.ext)
		c.Entitlements = append(c.Entitlements, formalEntRefRequest{RT: hexStr(e.rt), RID: hexStr(e.rid), Ext: hexStr(e.ext)})
	}
	lookup := "fresh" + g.utf8String(0, 2)
	if g.r.IntN(4) != 0 {
		lookup = exts[g.r.IntN(len(exts))]
	}
	c.Lookup = hexStr(lookup)
	return c
}

func (g formalGen) syncCase(i int) formalSyncRequest {
	ids := []string{"s1", "s2", "s3"}
	startTypes := []string{"full", "partial", "resources_only"}
	latestTypes := []string{"any", "full", "partial", "resources_only"}
	c := formalSyncRequest{Name: fmt.Sprintf("property/sync/%d", i)}
	for range 1 + g.r.IntN(7) {
		var op formalSyncOpRequest
		switch g.r.IntN(5) {
		case 0:
			op = formalSyncOpRequest{Op: "start_new", ID: strPtr(ids[g.r.IntN(len(ids))]), Type: strPtr(startTypes[g.r.IntN(len(startTypes))])}
		case 1:
			op = formalSyncOpRequest{Op: "write"}
		case 2:
			op = formalSyncOpRequest{Op: "end"}
		case 3:
			id := ids[g.r.IntN(len(ids))]
			if g.r.IntN(5) == 0 {
				id = "s9"
			}
			op = formalSyncOpRequest{Op: "resume", ID: strPtr(id)}
		default:
			op = formalSyncOpRequest{Op: "latest_finished", Type: strPtr(latestTypes[g.r.IntN(len(latestTypes))])}
		}
		c.Ops = append(c.Ops, op)
	}
	return c
}

func buildFormalRequest(seed uint64, n int) *formalRequest {
	g := formalGen{r: rand.New(rand.NewPCG(seed, seed))} //nolint:gosec // A seeded generator makes a failing case replayable.
	req := &formalRequest{Version: formalOracleVersion}
	for i := range n {
		req.Keys = append(req.Keys, g.keyCase(i))
		req.EntitlementStrip = append(req.EntitlementStrip, g.stripCase())
		req.Writes = append(req.Writes, g.writesCase(i))
		req.Pagination = append(req.Pagination, g.paginationCase(i))
		req.BareID = append(req.BareID, g.bareIDCase(i))
		req.Sync = append(req.Sync, g.syncCase(i))
	}
	return req
}

func formalPropertyN(t *testing.T) int {
	t.Helper()
	s := os.Getenv("C1Z_FORMAL_PROPERTY_N")
	if s == "" {
		return 200
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < 1 {
		t.Fatalf("C1Z_FORMAL_PROPERTY_N=%q, want a positive integer", s)
	}
	return n
}

func formalPropertySeed(t *testing.T) uint64 {
	t.Helper()
	s := os.Getenv("C1Z_FORMAL_PROPERTY_SEED")
	if s == "" {
		return uint64(time.Now().UnixNano())
	}
	seed, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		t.Fatalf("C1Z_FORMAL_PROPERTY_SEED=%q: %v", s, err)
	}
	return seed
}

func runFormalOracle(t *testing.T, oracle string, request []byte) []byte {
	t.Helper()
	cmd := exec.CommandContext(t.Context(), oracle, "--respond") //nolint:gosec // The path comes from C1Z_FORMAL_ORACLE, set by the developer.
	cmd.Stdin = bytes.NewReader(request)
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		t.Fatalf("%s --respond: %v\nstderr:\n%s", oracle, err, stderr.String())
	}
	if stdout.Len() == 0 {
		t.Fatalf("%s --respond wrote nothing to stdout\nstderr:\n%s", oracle, stderr.String())
	}
	return stdout.Bytes()
}

func requireFormalResponseMatchesRequest(t *testing.T, req *formalRequest, resp *formalCases) {
	t.Helper()
	requireNames := func(family string, want, got []string) {
		t.Helper()
		if !equalStrings(want, got) {
			t.Fatalf("%s: response case names differ from the request:\n got  %v\n want %v", family, got, want)
		}
	}
	names := func(n int, name func(int) string) []string {
		out := make([]string, n)
		for i := range out {
			out[i] = name(i)
		}
		return out
	}
	requireNames("keys", names(len(req.Keys), func(i int) string { return req.Keys[i].Name }),
		names(len(resp.Keys), func(i int) string { return resp.Keys[i].Name }))
	requireNames("writes", names(len(req.Writes), func(i int) string { return req.Writes[i].Name }),
		names(len(resp.Writes), func(i int) string { return resp.Writes[i].Name }))
	requireNames("pagination", names(len(req.Pagination), func(i int) string { return req.Pagination[i].Name }),
		names(len(resp.Pagination), func(i int) string { return resp.Pagination[i].Name }))
	requireNames("bare_id", names(len(req.BareID), func(i int) string { return req.BareID[i].Name }),
		names(len(resp.BareID), func(i int) string { return resp.BareID[i].Name }))
	requireNames("sync", names(len(req.Sync), func(i int) string { return req.Sync[i].Name }),
		names(len(resp.Sync), func(i int) string { return resp.Sync[i].Name }))
	for i, r := range req.EntitlementStrip {
		c := resp.EntitlementStrip[i]
		if hexStr(c.RT.b) != r.RT || hexStr(c.RID.b) != r.RID || hexStr(c.Ext.b) != r.Ext {
			t.Fatalf("entitlement_strip[%d]: response inputs (%s, %s, %s) differ from the request (%s, %s, %s)",
				i, hexStr(c.RT.b), hexStr(c.RID.b), hexStr(c.Ext.b), r.RT, r.RID, r.Ext)
		}
	}
}

// formalCaseJSON returns the request and response JSON of one case for a
// failure log.
func formalCaseJSON(req *formalRequest, resp *formalCases, family string, i int) (string, string) {
	var rq, rs any
	switch family {
	case "keys":
		rq, rs = req.Keys[i], resp.Keys[i]
	case "entitlement_strip":
		rq, rs = req.EntitlementStrip[i], resp.EntitlementStrip[i]
	case "writes":
		rq, rs = req.Writes[i], resp.Writes[i]
	case "pagination":
		rq, rs = req.Pagination[i], resp.Pagination[i]
	case "bare_id":
		rq, rs = req.BareID[i], resp.BareID[i]
	case "sync":
		rq, rs = req.Sync[i], resp.Sync[i]
	}
	a, errA := json.Marshal(rq)
	b, errB := json.Marshal(rs)
	if err := errors.Join(errA, errB); err != nil {
		return "marshal: " + err.Error(), ""
	}
	return string(a), string(b)
}

// TestFormalProperty generates random inputs, has the Lean model compute
// the expected results through `c1z-oracle --respond`, and replays them
// against this engine. See "Go-side environment" in
// formal/c1z/ORACLE_SCHEMA.md.
func TestFormalProperty(t *testing.T) {
	oracle := os.Getenv("C1Z_FORMAL_ORACLE")
	if oracle == "" {
		t.Skip("C1Z_FORMAL_ORACLE is unset; set it to the c1z-oracle binary (formal/c1z/.lake/build/bin/c1z-oracle) to run")
	}
	n := formalPropertyN(t)
	seed := formalPropertySeed(t)
	t.Logf("C1Z_FORMAL_PROPERTY_SEED=%d C1Z_FORMAL_PROPERTY_N=%d", seed, n)

	req := buildFormalRequest(seed, n)
	body, err := json.Marshal(req)
	if err != nil {
		t.Fatalf("marshal request: %v", err)
	}
	out := runFormalOracle(t, oracle, body)
	resp, err := decodeFormalCases(bytes.NewReader(out))
	if err != nil {
		t.Fatalf("oracle response: %v", err)
	}
	for family, got := range resp.Counts {
		if got != n {
			t.Fatalf("counts[%q] = %d, want %d", family, got, n)
		}
	}
	requireFormalResponseMatchesRequest(t, req, resp)
	replayFormalCases(t, resp, func(t *testing.T, family string, i int) {
		rq, rs := formalCaseJSON(req, resp, family, i)
		t.Logf("seed %d, %s[%d]\nrequest:  %s\nresponse: %s", seed, family, i, rq, rs)
	})
}
